import sys
from collections import defaultdict, deque

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    adj = defaultdict(list)
    for _ in range(m):
        x, y = map(int, sys.stdin.readline().split())
        adj[x].append(y)
        adj[y].append(x)

    visited = [False] * (n + 1)
    res = 0

    for i in range(1, n + 1):
        if not visited[i]:
            q = deque()
            q.append(i)
            visited[i] = True
            is_cycle = False
            parent = {}
            parent[i] = -1
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        parent[v] = u
                        q.append(v)
                    elif parent[u] != v and parent.get(v, -1) != u:
                        is_cycle = True
            if not is_cycle:
                res += 1
    print(res)

main()
